import{_ as t,H as i,f as s,i as l}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"50 | RESTfulWebServices（14）：分解任务与Setup测试","description":"","frontmatter":{},"headers":[{"level":2,"title":"回顾架构愿景与任务列表","slug":"回顾架构愿景与任务列表","link":"#回顾架构愿景与任务列表","children":[]},{"level":2,"title":"视频演示","slug":"视频演示","link":"#视频演示","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·TDD项目实战70讲/50｜RESTfulWebServices（14）：分解任务与Setup测试.md","filePath":"徐昊·TDD项目实战70讲/50｜RESTfulWebServices（14）：分解任务与Setup测试.md","lastUpdated":1795563222000}'),p={name:"徐昊·TDD项目实战70讲/50｜RESTfulWebServices（14）：分解任务与Setup测试.md"};function o(a,e,r,n,u,E){return i(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="_50-restfulwebservices-14-分解任务与setup测试" tabindex="-1">50 | RESTfulWebServices（14）：分解任务与Setup测试 <a class="header-anchor" href="#_50-restfulwebservices-14-分解任务与setup测试" aria-label="Permalink to &quot;50 | RESTfulWebServices（14）：分解任务与Setup测试&quot;">​</a></h1><p>你好，我是徐昊。今天我们继续使用 TDD 的方式实现 RESTful Web Services。</p><h2 id="回顾架构愿景与任务列表" tabindex="-1">回顾架构愿景与任务列表 <a class="header-anchor" href="#回顾架构愿景与任务列表" aria-label="Permalink to &quot;回顾架构愿景与任务列表&quot;">​</a></h2><p>目前我们的架构愿景如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/50/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/50/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/50/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/50/2.png" alt=""></a></p><p>目前的任务列表为（仅列出与当前相关的模块），这里的列表我们合并了从 ResourceServlet发现的需求，以及在第 40 讲中分解的任务：</p><ul><li><p>ResourceRouter</p></li><li><p>在处理请求派分时，可以支持多级子资源（Sub-Resource）</p></li><li><p>在处理请求派分时，可以根据客户端提供的超媒体类型，选择对应的资源方法（Resource Method）</p></li><li><p>在处理请求派分时，可以根据客户端提供的 Http 方法，选择对应的资源方法</p></li><li><p>资源方法可以返回 Java 对象，由 Runtime 自行推断正确的返回状态</p></li><li><p>资源方法可以不明确指定返回的超媒体类型，由 Runtime 自行推断，比如，资源方法标注了 Produces 标注，那么就使用标注提供的超媒体类型等</p></li><li><p>资源方法可按找期望的类型，访问 Http 请求的内容</p></li><li><p>资源对象和资源方法可接受环境组件的注入</p></li><li><p>将 Resource Method 的返回值包装为 Response 对象</p></li></ul><p>继续细化任务列表，根据架构愿景，分配到不同的模块：</p><ul><li><p>ResourceRouter</p></li><li><p>将 Resource Method 的返回值包装为 Response 对象</p></li><li><p>根据与 Path 匹配结果，降序排列 RootResource，选择第一个的 RootResource</p></li><li><p>如果没有匹配的 RootResource，则构造 404 的 Response</p></li><li><p>如果返回的 RootResource 中无法匹配剩余 Path，则构造 404 的 Response</p></li><li><p>如果 ResourceMethod 返回 null，则构造 204 的 Response</p></li><li><p>Resource/RootResource/ResourceMethod</p></li><li><p>在处理请求派分时，可以支持多级子资源（Sub-Resource）</p></li><li><p>在处理请求派分时，可以根据客户端提供的超媒体类型，选择对应的资源方法（Resource Method）</p></li><li><p>在处理请求派分时，可以根据客户端提供的 Http 方法，选择对应的资源方法</p></li><li><p>资源方法可以返回 Java 对象，由 Runtime 自行推断正确的返回状态</p></li><li><p>资源方法可以不明确指定返回的超媒体类型，由 Runtime 自行推断，比如，资源方法标注了 Produces 标注，那么就使用标注提供的超媒体类型等</p></li><li><p>资源方法可按找期望的类型，访问 Http 请求的内容</p></li><li><p>资源对象和资源方法可接受环境组件的注入</p></li></ul><p>可以看到在当前架构愿景下，原本设计的需求被分入了Resource/RootResource/ResourceMethod 模块中。</p><h2 id="视频演示" tabindex="-1">视频演示 <a class="header-anchor" href="#视频演示" aria-label="Permalink to &quot;视频演示&quot;">​</a></h2><p>下面进入今日的开发：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/50/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7TDD%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%9870%E8%AE%B2/images/50/3.jpeg" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>完成后的代码里其实是有一点问题的，请问问题出在哪儿？</p><p>欢迎把你的想法分享在留言区，也欢迎把你的项目代码分享出来。相信经过你的思考与实操，学习效果会更好！</p>',17)])])}const R=t(p,[["render",o]]);export{h as __pageData,R as default};
